package org.springframework.samples.petclinic.integration;

import static org.assertj.core.api.Assertions.assertThat;

import java.net.URI;

import org.openqa.selenium.By;
import org.openqa.selenium.TimeoutException;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.ui.WebDriverWait;

import io.cucumber.java.en.Given;
import io.cucumber.java.en.Then;
import io.cucumber.java.en.When;

/**
 * Generic, reusable steps (go to a path, click by text, check text, check a field or a
 * table). Scenarios, written by hand or generated by the post-merge QA agent, are built
 * from these steps and the ones in {@link StepDefinition}. This class has no Spring
 * annotations on purpose: {@link SpringIntegrationTest} carries the one context
 * configuration.
 */
public class GenericSteps {

	private static final long WAIT_SECONDS = 20L;

	private final WebDriver webDriver = Browser.webDriver;

	@Given("^I go to the path \"([^\"]*)\"$")
	public void goToPath(String path) {
		webDriver.navigate().to(StepDefinition.BASE_URL + path);
	}

	@When("^I click on the link with text \"([^\"]*)\"$")
	public void clickOnLinkWithText(String text) {
		click(By.xpath("//a[normalize-space(.)=" + literal(text) + "]"));
	}

	@When("^I click on the button with text \"([^\"]*)\"$")
	public void clickOnButtonWithText(String text) {
		// a "button" is a <button>, a submit input, or a link styled as a button (class
		// "btn"), e.g. Add Owner / Edit Owner
		click(By.xpath("//button[normalize-space(.)=" + literal(text) + "] | //input[@type='submit' and @value="
				+ literal(text) + "] | //a[contains(concat(' ', normalize-space(@class), ' '), ' btn ') and "
				+ "normalize-space(.)=" + literal(text) + "]"));
	}

	@When("^I clear the field named \"([^\"]*)\"$")
	public void clearField(String name) {
		webDriver.findElement(By.name(name)).clear();
	}

	@Then("^I should see the text \"([^\"]*)\"$")
	public void shouldSeeText(String text) {
		try {
			new WebDriverWait(webDriver, WAIT_SECONDS).until(driver -> bodyText().contains(text));
		}
		catch (TimeoutException ex) {
			// fall through: the assertion below reports what the page really shows
		}
		assertThat(bodyText()).contains(text);
	}

	@Then("^I should not see the text \"([^\"]*)\"$")
	public void shouldNotSeeText(String text) {
		assertThat(bodyText()).doesNotContain(text);
	}

	@Then("^the field named \"([^\"]*)\" should have the value \"([^\"]*)\"$")
	public void fieldShouldHaveValue(String name, String value) {
		assertThat(webDriver.findElement(By.name(name)).getAttribute("value")).isEqualTo(value);
	}

	@Then("^the table \"([^\"]*)\" should have (\\d+) rows?$")
	public void tableShouldHaveRows(String tableId, int expected) {
		assertThat(webDriver.findElements(By.cssSelector("#" + tableId + " tbody tr")).size()).isEqualTo(expected);
	}

	@Then("^the current path should be \"([^\"]*)\"$")
	public void currentPathShouldBe(String path) {
		assertThat(URI.create(webDriver.getCurrentUrl()).getPath()).isEqualTo(path);
	}

	private void click(By selector) {
		new WebDriverWait(webDriver, WAIT_SECONDS).until(driver -> driver.findElement(selector).isDisplayed());
		WebElement element = webDriver.findElement(selector);
		element.click();
	}

	private String bodyText() {
		return webDriver.findElement(By.tagName("body")).getText();
	}

	/** An XPath string literal that is also valid when the text contains a quote. */
	private static String literal(String text) {
		if (!text.contains("'")) {
			return "'" + text + "'";
		}
		if (!text.contains("\"")) {
			return "\"" + text + "\"";
		}
		return "concat('" + text.replace("'", "', \"'\", '") + "')";
	}

}
